   /* Internal startIdx-anchored open behind cdlEveningDojiStarOpen (composition seam). */
   CdlEveningDojiStarStream cdlEveningDojiStarOpenInternal( double inOpen[], double inHigh[], double inLow[], double inClose[], int startIdx, double optInPenetration )
   {
      CdlEveningDojiStarStream sp = new CdlEveningDojiStarStream(this);
      RetCode retCode = cdlEveningDojiStarOpenBody(sp, inOpen, inHigh, inLow, inClose, startIdx, optInPenetration);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      if( retCode == RetCode.OutOfRangeEndIndex ) {
         throw new InsufficientHistoryException("TA_CDLEVENINGDOJISTAR open: history shorter than lookback + 1");
      }
      if( retCode == RetCode.InternalError ) {
         throw new IllegalStateException("TA_CDLEVENINGDOJISTAR open: internal error");
      }
      throw new IllegalArgumentException("TA_CDLEVENINGDOJISTAR open: " + retCode);
   }
   /**
    * Open a live CDLEVENINGDOJISTAR stream over the warm-up history; the handle's
    * {@code value()} starts at the last history bar's value — bit-identical
    * to {@link Core#cdlEveningDojiStar} at that bar.
    * <p>The history must hold at least {@code cdlEveningDojiStarLookback(...) + 1} bars
    * (unstable-period aware), or {@link InsufficientHistoryException} is
    * thrown. Out-of-range parameters throw {@link IllegalArgumentException}
    * ({@code Integer.MIN_VALUE} selects an integer parameter's documented
    * default, as in the batch API).
    */
   public CdlEveningDojiStarStream cdlEveningDojiStarOpen( double inOpen[], double inHigh[], double inLow[], double inClose[], double optInPenetration )
   {
      return cdlEveningDojiStarOpenInternal(inOpen, inHigh, inLow, inClose, 0, optInPenetration);
   }
   /**
    * {@link Core#cdlEveningDojiStarOpen} that also fills the output array(s) bit-identically
    * to {@link Core#cdlEveningDojiStar} over the whole history in the same single pass
    * (no separate batch call needed for the warm-up plot). Output arrays must
    * not alias the inputs or each other, and must hold
    * {@code historyLen - lookback} values.
    * <p>The range written is on the returned handle:
    * {@link CdlEveningDojiStarStream#fillRange()}.
    */
   public CdlEveningDojiStarStream cdlEveningDojiStarOpenAndFill( double inOpen[], double inHigh[], double inLow[], double inClose[], double optInPenetration, int outInteger[] )
   {
      CdlEveningDojiStarStream sp = new CdlEveningDojiStarStream(this);
      MInteger outBegIdx = new MInteger();
      MInteger outNBElement = new MInteger();
      RetCode retCode = cdlEveningDojiStarOpenAndFillBody(sp, inOpen, inHigh, inLow, inClose, optInPenetration, outBegIdx, outNBElement, outInteger);
      sp.fillRange = new OutRange(outBegIdx.value, outNBElement.value);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      if( retCode == RetCode.OutOfRangeEndIndex ) {
         throw new InsufficientHistoryException("TA_CDLEVENINGDOJISTAR openAndFill: history shorter than lookback + 1");
      }
      if( retCode == RetCode.InternalError ) {
         throw new IllegalStateException("TA_CDLEVENINGDOJISTAR openAndFill: internal error");
      }
      throw new IllegalArgumentException("TA_CDLEVENINGDOJISTAR openAndFill: " + retCode);
   }
