      MInteger outBegIdx = new MInteger();
      MInteger outNBElement = new MInteger();
      cdlEveningStarUnguardedInternal(startIdx, endIdx, inOpen, inHigh, inLow, inClose, optInPenetration, outBegIdx, outNBElement, outInteger);
