   /* Internal startIdx-anchored open behind cdlHaramiOpen (composition seam). */
   CdlHaramiStream cdlHaramiOpenInternal( double inOpen[], double inHigh[], double inLow[], double inClose[], int startIdx )
   {
      CdlHaramiStream sp = new CdlHaramiStream(this);
      RetCode retCode = cdlHaramiOpenBody(sp, inOpen, inHigh, inLow, inClose, startIdx);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      if( retCode == RetCode.OutOfRangeEndIndex ) {
         throw new InsufficientHistoryException("TA_CDLHARAMI open: history shorter than lookback + 1");
      }
      if( retCode == RetCode.InternalError ) {
         throw new IllegalStateException("TA_CDLHARAMI open: internal error");
      }
      throw new IllegalArgumentException("TA_CDLHARAMI open: " + retCode);
   }
   /**
    * Open a live CDLHARAMI stream over the warm-up history; the handle's
    * {@code value()} starts at the last history bar's value — bit-identical
    * to {@link Core#cdlHarami} at that bar.
    * <p>The history must hold at least {@code cdlHaramiLookback(...) + 1} bars
    * (unstable-period aware), or {@link InsufficientHistoryException} is
    * thrown. Out-of-range parameters throw {@link IllegalArgumentException}
    * ({@code Integer.MIN_VALUE} selects an integer parameter's documented
    * default, as in the batch API).
    */
   public CdlHaramiStream cdlHaramiOpen( double inOpen[], double inHigh[], double inLow[], double inClose[] )
   {
      return cdlHaramiOpenInternal(inOpen, inHigh, inLow, inClose, 0);
   }
   /**
    * {@link Core#cdlHaramiOpen} that also fills the output array(s) bit-identically
    * to {@link Core#cdlHarami} over the whole history in the same single pass
    * (no separate batch call needed for the warm-up plot). Output arrays must
    * not alias the inputs or each other, and must hold
    * {@code historyLen - lookback} values.
    * <p>The range written is on the returned handle:
    * {@link CdlHaramiStream#fillRange()}.
    */
   public CdlHaramiStream cdlHaramiOpenAndFill( double inOpen[], double inHigh[], double inLow[], double inClose[], int outInteger[] )
   {
      CdlHaramiStream sp = new CdlHaramiStream(this);
      MInteger outBegIdx = new MInteger();
      MInteger outNBElement = new MInteger();
      RetCode retCode = cdlHaramiOpenAndFillBody(sp, inOpen, inHigh, inLow, inClose, outBegIdx, outNBElement, outInteger);
      sp.fillRange = new OutRange(outBegIdx.value, outNBElement.value);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      if( retCode == RetCode.OutOfRangeEndIndex ) {
         throw new InsufficientHistoryException("TA_CDLHARAMI openAndFill: history shorter than lookback + 1");
      }
      if( retCode == RetCode.InternalError ) {
         throw new IllegalStateException("TA_CDLHARAMI openAndFill: internal error");
      }
      throw new IllegalArgumentException("TA_CDLHARAMI openAndFill: " + retCode);
   }
