   /* Internal startIdx-anchored open behind cdlShortLineOpen (composition seam). */
   CdlShortLineStream cdlShortLineOpenInternal( double inOpen[], double inHigh[], double inLow[], double inClose[], int startIdx )
   {
      CdlShortLineStream sp = new CdlShortLineStream(this);
      RetCode retCode = cdlShortLineOpenBody(sp, inOpen, inHigh, inLow, inClose, startIdx);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      if( retCode == RetCode.OutOfRangeEndIndex ) {
         throw new InsufficientHistoryException("TA_CDLSHORTLINE open: history shorter than lookback + 1");
      }
      if( retCode == RetCode.InternalError ) {
         throw new IllegalStateException("TA_CDLSHORTLINE open: internal error");
      }
      throw new IllegalArgumentException("TA_CDLSHORTLINE open: " + retCode);
   }
   /**
    * Open a live CDLSHORTLINE stream over the warm-up history; the handle's
    * {@code value()} starts at the last history bar's value — bit-identical
    * to {@link Core#cdlShortLine} at that bar.
    * <p>The history must hold at least {@code cdlShortLineLookback(...) + 1} bars
    * (unstable-period aware), or {@link InsufficientHistoryException} is
    * thrown. Out-of-range parameters throw {@link IllegalArgumentException}
    * ({@code Integer.MIN_VALUE} selects an integer parameter's documented
    * default, as in the batch API).
    */
   public CdlShortLineStream cdlShortLineOpen( double inOpen[], double inHigh[], double inLow[], double inClose[] )
   {
      return cdlShortLineOpenInternal(inOpen, inHigh, inLow, inClose, 0);
   }
   /**
    * {@link Core#cdlShortLineOpen} that also fills the output array(s) bit-identically
    * to {@link Core#cdlShortLine} over the whole history in the same single pass
    * (no separate batch call needed for the warm-up plot). Output arrays must
    * not alias the inputs or each other, and must hold
    * {@code historyLen - lookback} values.
    * <p>The range written is on the returned handle:
    * {@link CdlShortLineStream#fillRange()}.
    */
   public CdlShortLineStream cdlShortLineOpenAndFill( double inOpen[], double inHigh[], double inLow[], double inClose[], int outInteger[] )
   {
      CdlShortLineStream sp = new CdlShortLineStream(this);
      MInteger outBegIdx = new MInteger();
      MInteger outNBElement = new MInteger();
      RetCode retCode = cdlShortLineOpenAndFillBody(sp, inOpen, inHigh, inLow, inClose, outBegIdx, outNBElement, outInteger);
      sp.fillRange = new OutRange(outBegIdx.value, outNBElement.value);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      if( retCode == RetCode.OutOfRangeEndIndex ) {
         throw new InsufficientHistoryException("TA_CDLSHORTLINE openAndFill: history shorter than lookback + 1");
      }
      if( retCode == RetCode.InternalError ) {
         throw new IllegalStateException("TA_CDLSHORTLINE openAndFill: internal error");
      }
      throw new IllegalArgumentException("TA_CDLSHORTLINE openAndFill: " + retCode);
   }
