         DCPeriodInt = (int)DCPeriod;
         tempReal = 0.0;
         for( j = 0; j < 50; j += 1 ) {
            if( j < DCPeriodInt ) {
               tempReal += (double)inReal[today - j];
            }
         }
         if( DCPeriodInt > 0 ) {
            tempReal = tempReal / (double)DCPeriodInt;
         }
         trendline = (Math.fma(2.0, iTrend2, Math.fma(4.0, tempReal, 3.0 * iTrend1)) + iTrend3) / 10.0;
