         double numerator = 0;
         double numeratorSub = 0;
         double numeratorAdd = 0;
         int i = 0;
         int outIdx = 0;
         int todayIdx = 0;
         int trailingIdx = 0;
         int middleIdx = 0;
         double factor = 0;
         double tempReal = 0;
         /* Identify the minimum number of price bar needed
          * to calculate at least one output.
          */
         lookbackTotal = optInTimePeriod - 1;
