            numeratorSub += tempReal;
            /* Step (2) */
            numeratorAdd -= tempReal;
            numerator += numeratorAdd;
            tempReal = inReal[todayIdx++];
            numeratorAdd += tempReal;
            /* Step (3) */
            numerator += tempReal;
            /* Step (4) */
            tempReal = inReal[trailingIdx++];
            lastValue_outReal = numerator * factor;
